import { NextResponse } from "next/server";
import { createServerSupabase } from "@/lib/supabase/server";
import { createAdminClient } from "@/lib/supabase/admin";
export async function GET(request:Request){try{const auth=await createServerSupabase();const {data:{user}}=await auth.auth.getUser();if(!user)return NextResponse.json({error:"Please log in."},{status:401});const db=createAdminClient();const {data:vendor}=await db.from("vendors").select("id").eq("owner_id",user.id).single();if(!vendor)return NextResponse.json({error:"Shop not found."},{status:404});const url=new URL(request.url);const after=url.searchParams.get("after");let query=db.from("orders").select("id,reference,customer_name,customer_phone,fulfilment,delivery_address,note,subtotal,total_amount,platform_fee,paystack_fee,vendor_amount,payment_status,fulfilment_status,paid_at,created_at,order_items(id,product_id,name_snapshot,unit_price,quantity,line_total)").eq("vendor_id",vendor.id).order("created_at",{ascending:false}).limit(100);if(after)query=query.gt("created_at",after);const {data,error}=await query;if(error)throw error;return NextResponse.json({orders:data||[]});}catch{return NextResponse.json({error:"Orders are unavailable right now."},{status:503});}}
